import {readFileSync,mkdirSync,writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {composeArcSections} from '../../scripts/v0/optimizer/arc_composition.ts';
import {composeContactSections} from '../../scripts/v0/optimizer/contact_composition.ts';
import {stylesForPhrases} from '../../scripts/produce/musical_repertoire.ts';
import {musicalDirectionCases} from '../../scripts/produce/musical_direction_cases.ts';
import {applyJolt,resolveJoltMs} from '../../scripts/produce/seed.ts';
import {normalizeCompilerTimeline} from '../../scripts/v0/optimizer/compiler_input.ts';
import {replayGalleryTrack,writeGalleryJson} from '../../scripts/gallery/artifacts.ts';
import {verifyMainConstruction} from '../../scripts/gallery/verify_construction.ts';
const mode=process.argv[2],out=`generated/repertoire-development-20260930/probe-${mode}`;mkdirSync(out,{recursive:true});
const old='generated/repertoire-20260930/confirmation',manifest=JSON.parse(readFileSync(`${old}/manifest.json`,'utf8'));
const results=[];
for(const d of musicalDirectionCases){
 const id=`${d.song}-341-baseline`,saved=JSON.parse(readFileSync(`${old}/${id}.json`,'utf8'));
 const construction=JSON.parse(readFileSync(`${old}/${id}/construction.json`,'utf8'));
 const source={track:saved.track,report:JSON.parse(readFileSync(`${old}/${id}/report.json`,'utf8')),rows:construction.rows};
 const spec=normalizeCompilerTimeline(applyJolt((await import(pathToFileURL(resolve(`productions/${d.song}/spec.ts`)).href)).default,resolveJoltMs()));
 const c=manifest.plan.cases.find(c=>c.id===d.song);
 const choices=mode==='fragments'?[.0003,.003,.03,.3,1,3,6,12]:[
  {profile:'scallops',profileStrength:1},
  {profile:'scallops',profileStrength:1,profileStart:.25,rippleCycles:2},
  {profile:'scallops',profileStrength:1,profileStart:.25,rippleCycles:1},
  {profile:'scallops',profileStrength:.6,profileStart:0,rippleCycles:1}];
 for(const [index,choice]of choices.entries()){
  const styles=stylesForPhrases(source.rows,[{title:'First phrase',window:d.guidance,style:mode==='fragments'?{}:choice as any},{title:'Later phrase',window:d.mixed,style:mode==='fragments'?{}:choice as any}]);
  const begin=performance.now();
  const result=mode==='fragments'?composeContactSections(spec,source as any,{sections:Object.keys(styles).map(Number),widths:[choice as number],budget:20000}):composeArcSections(spec,351,source as any,styles,1000000);
  const track=mode==='fragments'?result.track:result.result.track;
  const replay=replayGalleryTrack(track,c,true);
  const name=`${d.song}-${index}`;
  const record={name,choice,seconds:(performance.now()-begin)/1000,physicalFrames:result.physicalFrames,valid:replay.grade.score.valid,rms:replay.grade.score.weightedAxisRms,
   fragments:mode==='fragments'?result.construction:undefined,verification:mode==='fragments'?undefined:verifyMainConstruction(track,result.result.rows,{radius:24,channel:12,sectionStyles:styles},Math.min(...Object.keys(styles).map(Number))),
   sourceTrackHash:saved.trackHash,styles};
  writeGalleryJson(out,`${name}.json`,{...record,result,replay});results.push(record);writeFileSync(`${out}/summary.json`,JSON.stringify(results));
  console.log(JSON.stringify({...record,fragments:record.fragments?{...record.fragments,provenance:undefined}:undefined}));
 }
}

